import java.text.Normalizer;
import java.util.Arrays;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import java.util.regex.Pattern;

/**
 * Which customers a query should return.
 *
 * <p>A customer matches when it satisfies both criteria:
 * <ul>
 *   <li>{@code name}: the text is split on whitespace into terms, and every term
 *       must appear inside the first name or the last name. Case and accents are
 *       ignored. An empty name matches everybody.</li>
 *   <li>{@code statuses}: the customer's status is one of these. An empty set
 *       matches everybody.</li>
 * </ul>
 *
 * @param name     text typed by the user; may be empty
 * @param statuses statuses to keep; empty means every status
 */
public record CustomerFilter(String name, Set<CustomerStatus> statuses) {

    /** Matches every customer. */
    public static final CustomerFilter NONE = new CustomerFilter("", Set.of());

    private static final Pattern COMBINING_MARKS = Pattern.compile("\\p{M}+");

    public CustomerFilter {
        name = (name == null) ? "" : name;
        statuses = (statuses == null) ? Set.of() : Set.copyOf(statuses);
    }

    /** Whether {@code customer} satisfies both the name and the status criteria. */
    public boolean matches(Customer customer) {
        return matchesName(customer) && matchesStatus(customer);
    }

    private boolean matchesName(Customer customer) {
        List<String> terms = terms(name);
        if (terms.isEmpty()) {
            return true;
        }
        String firstName = fold(customer.firstName());
        String lastName = fold(customer.lastName());
        return terms.stream().allMatch(term -> firstName.contains(term) || lastName.contains(term));
    }

    private boolean matchesStatus(Customer customer) {
        return statuses.isEmpty() || statuses.contains(customer.status());
    }

    private static List<String> terms(String text) {
        return Arrays.stream(fold(text).trim().split("\\s+"))
                .filter(term -> !term.isEmpty())
                .toList();
    }

    /**
     * Lower-cases {@code text} and strips accents, so that {@code Mäkinen} and
     * {@code makinen} compare equal. Lower-casing comes first so that the
     * decomposed form of a capital letter is also stripped.
     */
    private static String fold(String text) {
        String lower = text.toLowerCase(Locale.ROOT);
        return COMBINING_MARKS.matcher(Normalizer.normalize(lower, Normalizer.Form.NFD)).replaceAll("");
    }
}
