+        UI.getCurrent().getPage().getHistory()
+                .replaceState(null, new Location("", new QueryParameters(parameters)));
+    }
+
+    /** Parses a comma-separated list of status names. Unknown names are ignored. */
+    private static Set<CustomerStatus> parseStatuses(String csv) {
+        Set<String> names = Arrays.stream(csv.split(","))
+                .map(String::trim)
+                .collect(Collectors.toSet());
+        return Arrays.stream(CustomerStatus.values())
+                .filter(status -> names.contains(status.name()))
+                .collect(Collectors.toSet());
+    }
