+    @Test
+    void typingFollowsTheFilterInTheAddressBarWithoutNewHistoryEntries() {
+        page.navigate(url("/"));
+        assertThat(page.getByText("Showing 500 of 500")).isVisible();
+        queryLog.clear();
+        int historyBefore = historyLength();
+
+        page.locator(NAME_FIELD).click();
+        page.keyboard().type("makinen", new Keyboard.TypeOptions().setDelay(60));
+
+        assertThat(page.getByText("Showing 15 of 500")).isVisible();
+        page.waitForURL(url -> "makinen".equals(queryParameters(url).get("name")));
+        assertEquals(historyBefore, historyLength());
+        // Typing must not cost a query per keystroke.
+        assertTrue(queryLog.countQueries().size() <= 2,
+                "Typing cost " + queryLog.countQueries().size() + " count queries: " + queryLog.countQueries());
+        assertTrue(queryLog.pageQueries().size() <= 2,
+                "Typing cost " + queryLog.pageQueries().size() + " page queries: " + queryLog.pageQueries());
+    }
+
+    @Test
+    void emptyingTheFilterRemovesItFromTheAddressBar() {
+        page.navigate(url("?name=vir"));
+        assertThat(page.getByText("Showing 15 of 500")).isVisible();
+
+        page.locator(NAME_FIELD).fill("");
+
+        assertThat(page.getByText("Showing 500 of 500")).isVisible();
+        page.waitForURL(url -> !queryParameters(url).containsKey("name"));
+        assertFalse(queryParameters(page.url()).containsKey("status"), "no status parameter: " + page.url());
+    }
+
+    @Test
+    void statusSelectionIsWrittenToTheAddressBarInDeclarationOrder() {
+        page.navigate(url("/"));
+        assertThat(page.getByText("Showing 500 of 500")).isVisible();
+
+        MultiSelectComboBoxElement status = MultiSelectComboBoxElement.getByLabel(page, "Status");
+        status.selectItems("CLOSED", "ACTIVE");
+
+        assertThat(page.getByText("Showing 333 of 500")).isVisible();
+        page.waitForURL(url -> "ACTIVE,CLOSED".equals(queryParameters(url).get("status")));
+    }
+
+    private String url(String pathAndQuery) {
+        return getUrl() + pathAndQuery.replaceFirst("^/", "");
+    }
+
+    private int historyLength() {
+        return ((Number) page.evaluate("history.length")).intValue();
+    }
+
+    /** The decoded query parameters of {@code address}. */
+    private static Map<String, String> queryParameters(String address) {
+        String query = URI.create(address).getRawQuery();
+        Map<String, String> parameters = new HashMap<>();
+        if (query == null) {
+            return parameters;
+        }
+        Arrays.stream(query.split("&"))
+                .map(pair -> pair.split("=", 2))
+                .forEach(pair -> parameters.put(
+                        URLDecoder.decode(pair[0], StandardCharsets.UTF_8),
+                        URLDecoder.decode(pair[1], StandardCharsets.UTF_8)));
+        return parameters;
+    }
+}
